 # --- LAYER 4: Ocean Prediction Atlas ---
  LAYER
      NAME "dccoceanpredictionforecastingsystemsatlas"
      TYPE POLYGON
      STATUS ON
      
      CONNECTIONTYPE OGR
      CONNECTION "/etc/mapserver/ocean_prediction_atlas.geojson"
      
      DATA "ocean_prediction_atlas" 
      
      PROJECTION
          "EPSG:4326"
      END
      TEMPLATE "blank.html"
      METADATA
        "wms_title" "Decade Collaborative Centre for Ocean Prediction ocean forecasting systems atlas"
        "wms_abstract" "This map shows the Ocean Forecasting Systems that provide ocean prediction services and modelling. It allows viewers to compare the distribution and characteristics of forecasting capacity around the world and to identify systems relevant to specific ocean regions or uses. It indicates the system title, responsible organisations, data policy, numerical and atmospheric models, main applications, variables used, and related links where available. This layer is extracted from the Atlas produced by the DCC for Ocean Prediction and its community in support of the Ocean Decade goal of a predicted ocean.
Operational ocean forecasting combines observations from satellites, buoys, floats, ships and other platforms with numerical models and data assimilation methods to describe the present state of the ocean and estimate how conditions may evolve."
        "wms_extent" "-180 -90 180 90"
        "wms_include_items" "all"
        "gml_include_items" "all"
        "wms_attribution_text" "Decade Collaborative Centre for Ocean Prediction"
          "wms_attribution_onlineresource" "https://www.unoceanprediction.org/en/homepage"
          "wms_metadataurl_href"   "https://www.unoceanprediction.org/en/atlas/models"
          "wms_metadataurl_format" "text/html"
          "wms_metadataurl_type"   "TC211"
          "wms_authority" "Decade Collaborative Centre for Ocean Prediction"
          "wms_authorityurl_name" "Decade Collaborative Centre for Ocean Prediction"
          "wms_authorityurl_href" "https://www.unoceanprediction.org/en/homepage"
          "wms_dataurl_href"   "https://www.unoceanprediction.org/en/api/atlas/models"
          "wms_dataurl_format" "application/json"
      END

      CLASSITEM "typeOfSystem"
      CLASS
          NAME "Biogeochemical"        
          STYLE
            COLOR 209 159 42
            OUTLINECOLOR 100 100 100
            WIDTH 1
            OPACITY 60
          END
      END  
    END
 # --- LAYER 5: UNESCO World Marine Heritage Sites ---
  LAYER
      NAME "marineheritagesites"
      TYPE POINT
      STATUS ON
      
      CONNECTIONTYPE OGR
      CONNECTION "/etc/mapserver/marine_world_heritage_sites.geojson.json"
      TEMPLATE "blank.html"
      METADATA
        "wms_title" "World Marine Heritage Sites recognised by UNESCO"
        "wms_abstract" "This map shows the global network of 51 marine heritage sites recognised by UNESCO. The mission of the world Heritage Marine Programme is to establish effective conservation of existing and potential marine areas of Outstanding Universal Value to make sure they will be maintained and thrive for generations to come."
        "wms_extent" "-180 -90 180 90"
        "wms_include_items" "all"
        "gml_include_items" "all"
        "wms_attribution_text" "UNESCO World Heritage Programme"
          "wms_attribution_onlineresource" "https://whc.unesco.org/en/list/"
          "wms_metadataurl_href"   "https://whc.unesco.org/en/list/?search=&themes=7&order=country"
          "wms_metadataurl_format" "text/html"
          "wms_metadataurl_type"   "TC211"
          "wms_authority" "UNESCO World Heritage Programme"
          "wms_authorityurl_name" "UNESCO World Heritage Programme"
          "wms_authorityurl_href" "https://whc.unesco.org/en/list/"
          "wms_dataurl_href"   "https://whc.unesco.org/en/list/?search=&themes=7&order=country"
          "wms_dataurl_format" "application/json"
      END

      CLASSITEM "cat"
      CLASS
          NAME "In Danger"
          EXPRESSION ([danger] = 1)        
          STYLE
            SYMBOL "circle"
            SIZE 10
            COLOR 194 32 51
            OUTLINECOLOR 194 32 51
            WIDTH 2
          END
      END   
      CLASS
      Name "Mixed"
      EXPRESSION ([cat] = 3)
      STYLE
      SYMBOL "circle"
      SIZE 10
      COLOR 252 192 63
      OUTLINECOLOR 45 154 71
      WIDTH 2
      END
    END
      CLASS
      Name "Natural"
      EXPRESSION ([cat] = 2)
      STYLE
      SYMBOL "circle"
      SIZE 10
      COLOR 114 183 67
      OUTLINECOLOR 114 183 67
      WIDTH 2
      END
    END   
  END
 # --- LAYER 6: ProtectedSeas Navigator ---
  LAYER
      NAME "protectedseasnavigator"
      TYPE POLYGON
      STATUS ON

      CONNECTIONTYPE OGR
      CONNECTION "/etc/mapserver/protectedseas_navigator.gpkg"
      DATA "protectedseas_navigator"

      PROJECTION
        "EPSG:4326"
      END

      TEMPLATE "blank.html"

      METADATA
        "wms_title" "ProtectedSeas Navigator - All Sites"
        "wms_abstract" "This map shows marine protected areas and other area-based management measures included in
the ProtectedSeas Navigator database. The layer provides information on the location and characteristics of managed marine areas around the world, including their designation, managing authority and Level of Fishing Protection. Fishing protection is represented using the ProtectedSeas Level of Fishing Protection score from 1 to 5, allowing users to compare the relative level of fishing restrictions across sites and explore patterns in marine protection and management."
        "wms_extent" "-180 -90 180 90"
        "wms_include_items" "all"
        "gml_include_items" "all"

        "wms_attribution_text" "ProtectedSeas"
        "wms_attribution_onlineresource" "https://navigatormap.org/"
        "wms_metadataurl_href" "https://navigatormap.org/data-request/"
        "wms_metadataurl_format" "text/html"
        "wms_metadataurl_type" "TC211"
        "wms_authority" "ProtectedSeas"
        "wms_authorityurl_name" "ProtectedSeas Navigator"
        "wms_authorityurl_href" "https://navigatormap.org/"
        "wms_dataurl_href" "https://services9.arcgis.com/lm7wE8a9YA9rKfzy/arcgis/rest/services/Navigator_AllSites_010925_attributes/FeatureServer/0"
        "wms_dataurl_format" "application/geo+json"
      END

      CLASS
        NAME "1 - Lowest fishing protection"
        EXPRESSION ([lfp] == 1)
        STYLE
          COLOR 160 170 182
          OUTLINECOLOR 35 35 35
          WIDTH 1
        END
      END

      CLASS
        NAME "2 - Low fishing protection"
        EXPRESSION ([lfp] == 2)
        STYLE
          COLOR 103 185 226
          OUTLINECOLOR 35 35 35
          WIDTH 1
        END
      END

      CLASS
        NAME "3 - Moderate fishing protection"
        EXPRESSION ([lfp] == 3)
        STYLE
          COLOR 39 177 152
          OUTLINECOLOR 35 35 35
          WIDTH 1
        END
      END

      CLASS
        NAME "4 - High fishing protection"
        EXPRESSION ([lfp] == 4)
        STYLE
          COLOR 249 177 26
          OUTLINECOLOR 247 247 247
          WIDTH 1
        END
      END

      CLASS
        NAME "5 - Highest fishing protection"
        EXPRESSION ([lfp] == 5)
        STYLE
          COLOR 233 73 99
          OUTLINECOLOR 35 35 35
          WIDTH 1
        END
      END
  END

END # MAP
